_Static_assert(sizeof(VHT_OP_IE) == 5, "VHT operation must occupy 5 bytes");
static void run(unsigned ch, unsigned old, unsigned bw, unsigned switching,
                unsigned dfs, unsigned ht, unsigned streams) {
    struct _RTMP_CHIP_CAP cap = {2};
    RTMP_ADAPTER ad = {&cap, {dfs}};
    struct DOT11_H h = {switching ? RD_SWITCHING_MODE : 0, old};
    struct wifi_dev w = {&h, bw, ht, streams, 155};
    unsigned char guarded[7];
    memset(guarded, 0xcc, sizeof(guarded));
    int n = build_vht_op_ie(&ad, bw, ch, &w, guarded + 1);
    if (n != 5 || guarded[0] != 0xcc || guarded[6] != 0xcc) abort();
    printf("%u,%u,%u,%u,%u,%u,%u,%02x%02x%02x%02x%02x\n",
           ch, old, bw, switching, dfs, ht, streams,
           guarded[1],guarded[2],guarded[3],guarded[4],guarded[5]);
}
int main(void) {
    unsigned channels[] = {36,40,44,48,52,56,60,64,100,104,108,112,116,120,124,128,132,136,140,144,149,153,157,161};
    for (unsigned bw=0; bw<4; bw++)
        for (unsigned i=0; i<sizeof(channels)/sizeof(channels[0]); i++) {
            if (bw==VHT_BW_160 && i>=16) continue;
            for (unsigned streams=1; streams<=4; streams++) {
                run(channels[i], channels[i], bw, 0, 1, HT_BW_40, streams);
                run(channels[i], channels[i], bw, 0, 1, HT_BW_20, streams);
            }
        }
    /* 切换中的操作元素仍描述原信道；目标信道由 CSA 元素描述。 */
    for (unsigned i=0; i<16; i++) {
        run(channels[(i+8)%16], channels[i], VHT_BW_160, 1, 1, HT_BW_40, 4);
        run(channels[(i+8)%16], channels[i], VHT_BW_160, 1, 0, HT_BW_40, 4);
        run(channels[(i+8)%16], channels[i], VHT_BW_80, 1, 1, HT_BW_40, 4);
    }
    struct _RTMP_CHIP_CAP cap = {2};
    RTMP_ADAPTER ad = {&cap, {1}};
    struct wifi_dev w = {0};
    unsigned char buf[5];
    if (build_vht_op_ie(&ad,2,60,NULL,buf)!=0) abort();
    if (build_vht_op_ie(&ad,2,60,&w,buf)!=0) abort();
    return 0;
}

